test('Feishu production authorization and profile path use only application-isolated local snapshot after warmup',async t=>{const{DirectorySnapshots}=await import('../dist/directory-sync/service.js');const f=setup(t),c=await ready(f);f.capabilities.saveDirectoryAccess('w','e',{allow:[rule(c,'channel_user','person')],deny:[]});const snapshots=new DirectorySnapshots(f.store,()=>f.service.directorySources());f.service.setDirectorySnapshots(snapshots);const user=scope(c),channel=connection(c);const before=f.state.calls;assert.equal(await f.capabilities.authorizeChannel(user,channel,'group'),false);assert.equal(f.state.calls,before,'missing snapshot must not perform a remote lookup');const task=snapshots.list('w').tasks[0];snapshots.manual('w',task.id);await snapshots.waitForIdle();const warm=f.state.calls;for(let i=0;i<10;i++)assert.equal(await f.capabilities.authorizeChannel(user,channel,'group'),true);assert.equal(f.state.calls,warm);f.state.fail='unavailable';snapshots.manual('w',task.id);await snapshots.waitForIdle();assert.equal(snapshots.list('w').tasks[0].stale,true);assert.equal(await f.capabilities.authorizeChannel(user,channel,'group'),true);const after=f.state.calls;assert.equal(await f.capabilities.authorizeChannel({...user,requesterIdentity:{idNamespace:'user_id',applicationId:c.appId}},channel,'group'),false);assert.equal(await f.capabilities.authorizeChannel({...user,requesterIdentity:{idNamespace:'open_id',applicationId:'other-app'}},channel,'group'),false);assert.equal(f.state.calls,after);const binding=await f.service.resolveBinding(c.id),profile=await f.service.describeActor(binding,{externalId:'person',idNamespace:'open_id',applicationId:'app',kind:'human',identityEvidence:'channel_verified'});assert.equal(profile.displayName,'Person');assert.equal(f.state.calls,after);assert.equal(f.service.directorySources().every(s=>s.provider==='feishu'),true);await snapshots.stop();t.diagnostic(`10 authorized inputs and profile read: remote user calls 0 after warmup (${warm-before} initial user read); stale failure continues from successful facts.`);});

